/// Wonky Sheets' localizations (suite 11 §4): ARB files in this folder,
/// generated by `flutter gen-l10n` (`l10n.yaml`) into `gen/`.
///
/// Widgets use [sheetsL10n]; code without a `BuildContext` (controllers,
/// commands, toasts) uses [sheetsL10nOf] with the shell services.
library;

import 'package:flutter/widgets.dart';
import 'package:wonky_app/wonky_app.dart';

import 'gen/sheets_localizations.dart';

export 'gen/sheets_localizations.dart';

/// A localized string resolved when shown (command titles, categories).
typedef SheetsText = String Function(SheetsLocalizations l);

/// The Sheets strings for [context] (English when the delegate is missing).
SheetsLocalizations sheetsL10n(BuildContext context) =>
    Localizations.of<SheetsLocalizations>(context, SheetsLocalizations) ??
    sheetsL10nEnglish;

/// The Sheets strings in the shell's current locale (no `BuildContext`).
SheetsLocalizations sheetsL10nOf(ShellServices services) {
  final c = services.navigatorContext;
  return c == null ? sheetsL10nEnglish : sheetsL10n(c);
}

/// English strings (the template locale).
final SheetsLocalizations sheetsL10nEnglish = lookupSheetsLocalizations(
  const Locale('en'),
);
